from math import gcd, comb

def check_condition(n):
    if gcd(n, 6) != 1:
        return False

    a_start = n // 3 + 1
    a_end = n // 2

    for a in range(a_start, a_end + 1):
        k = n - 2*a
        m = a - 1
        r = n - 2*a - 1
        if r < 0 or r > m:
            coeff = 0
        else:
            coeff = comb(m, r)

        if coeff % k != 0:
            return False

    return True

results = []
for n in range(2, 200):
    if check_condition(n):
        results.append(n)

print(f"Count: {len(results)}")
print(f"Values: {results}")
